-- =============================================================================
-- YTS Blog inserts from SEO markdown drafts (2026-09-06)
-- Safe to re-run: INSERT IGNORE skips existing slugs (unique key on slug)
-- Also adds metaTitle / metaDescription if missing on hosted DB
-- =============================================================================

-- 1) Ensure SEO columns exist (no-op if already present)
SET @db := DATABASE();

SET @sql := (
  SELECT IF(
    EXISTS (
      SELECT 1 FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = @db AND TABLE_NAME = 'blog' AND COLUMN_NAME = 'metaTitle'
    ),
    'SELECT 1',
    'ALTER TABLE `blog` ADD COLUMN `metaTitle` varchar(70) DEFAULT NULL AFTER `excerpt`'
  )
);
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @sql := (
  SELECT IF(
    EXISTS (
      SELECT 1 FROM information_schema.COLUMNS
      WHERE TABLE_SCHEMA = @db AND TABLE_NAME = 'blog' AND COLUMN_NAME = 'metaDescription'
    ),
    'SELECT 1',
    'ALTER TABLE `blog` ADD COLUMN `metaDescription` varchar(160) DEFAULT NULL AFTER `metaTitle`'
  )
);
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- 2) Insert articles
INSERT IGNORE INTO `blog` (
  `slug`, `title`, `excerpt`, `metaTitle`, `metaDescription`,
  `category`, `author`, `publishedAt`, `readingMinutes`,
  `coverImage`, `coverAlt`, `tags`, `body`,
  `isFeatured`, `isPublished`, `isActive`,
  `createdBy`, `createdDate`
) VALUES (
  'self-drive-car-rental-sri-lanka',
  'Self-Drive Car Rental in Sri Lanka: How to Choose the Right Vehicle (2026 Guide)',
  'Self-drive car rental in Sri Lanka lets you rent an automatic vehicle without a driver — but your home licence and IDP alone are not enough. Here is how permits, vehicle types, and booking actually work in 2026.',
  'Self-Drive Car Rental Sri Lanka Guide (2026)',
  'Planning to self-drive in Sri Lanka? Compare permit rules, vehicle types and rental costs, then book an automatic car with YTS Enterprises.',
  'Car rentals',
  'YTS Team',
  '2026-09-06',
  8,
  'https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?auto=format&fit=crop&w=1600&q=80',
  'Automatic rental hatchbacks including a Suzuki Wagon R and Toyota Axio parked outside a Colombo car rental office, illustrating economy self-drive options in Sri Lanka.',
  '["self-drive","car rental","Sri Lanka","IDP","Colombo"]',
  '[{"type":"p","text":"Self-drive car rental in Sri Lanka lets you rent an automatic vehicle without a driver, but it comes with one non-negotiable step most first-timers miss: your home licence and International Driving Permit (IDP) alone are not enough — you also need a local Sri Lankan permit before you can legally get behind the wheel."},{"type":"h2","text":"Key takeaways"},{"type":"ul","items":["Sort your permit before pickup. Foreign visitors need an IDP plus a Sri Lankan Recognition Permit (from AA Ceylon) or a Temporary Driving Licence (from the Department of Motor Traffic) — an IDP by itself will not satisfy a police checkpoint or a rental company.","Match the vehicle to the road, not just the group size. Automatic economy hatchbacks handle Colombo traffic and coastal roads easily; SUVs and minivans earn their keep on hill-country routes or larger group transfers.","Book with a local operator that inspects between rentals. Well-maintained, recently serviced vehicles matter more in Sri Lanka''s mix of expressways, city traffic, and narrower rural roads than they might elsewhere."]},{"type":"h2","text":"What is self-drive car rental & how it works"},{"type":"p","text":"Self-drive car rental is a service where you rent a vehicle and drive it yourself for a set period, without a chauffeur. In Sri Lanka, this typically means an automatic, petrol-powered car rented by the day or week, with a security deposit, agreed mileage terms, and a fixed fuel and return policy set out in the rental agreement."},{"type":"p","text":"Most local operators, including YTS Enterprises, rent on a straightforward daily basis: you choose your dates and vehicle category, pay a deposit, and collect the car with a full tank and a documented condition report. The rental agreement will spell out the fuel policy (usually \\"return as received\\"), any mileage cap, and what a collision damage waiver does and does not cover — worth reading before you sign, since this is where most disputes at drop-off actually come from."},{"type":"p","text":"Sri Lanka drives on the left, in right-hand-drive vehicles, which is comfortable for visitors from the UK, India, Australia, or similar markets and takes most others about a day to adjust to."},{"type":"h2","text":"Step-by-step framework for renting a self-drive car in Sri Lanka"},{"type":"ul","items":["Decide your trip type and group size. A coastal weekend for two calls for a different car than a ten-day island loop with four people and luggage.","Sort your driving permit before you travel. As of 2026, foreign nationals need their home licence and an IDP, converted into a Sri Lankan Recognition Permit (via AA Ceylon) or a Temporary Driving Licence (via the Department of Motor Traffic). Since August 2025, a same-day permit counter has also been operating at Bandaranaike International Airport. Rules can shift, so confirm current requirements with the DMT (dmt.gov.lk) or AA Ceylon before you fly.","Compare vehicle categories and daily rates rather than booking the first listing you see — fuel type, transmission, and luggage space all affect the real cost of a trip.","Book and pay the deposit, ideally with an operator who shows you the vehicle''s condition report and fuel policy upfront rather than after you have paid.","Inspect the car at pickup. Walk around it, photograph any existing marks, and confirm the fuel gauge reading matches what is on the paperwork.","Drive on the left, respect posted limits — generally 50 km/h in built-up areas, 70 km/h on open roads, and 100 km/h on expressways — and keep your permit, passport, and rental agreement with you, since checkpoints are common on highways and in tourist areas."]},{"type":"h2","text":"Which vehicle fits your trip"},{"type":"ul","items":["Economy hatchback (e.g. Suzuki Wagon R, Toyota Avanza): best for solo travellers, couples, city + coastal driving — easiest to park and manoeuvre; lowest fuel cost per kilometre.","Compact sedan (e.g. Toyota Axio): best for small families and business travel — extra boot space without sacrificing manoeuvrability.","SUV (e.g. MG ZS): best for groups needing more clearance — more comfortable on hill-country and less-maintained rural roads.","Luxury minivan (e.g. Toyota Vellfire): best for multi-day group transfers and airport pickups — seats and luggage space for larger parties in one vehicle."]},{"type":"h2","text":"Choosing the right vehicle for your trip"},{"type":"p","text":"If your itinerary is mostly Colombo, the west coast, and the south (Galle, Mirissa, Unawatuna), an automatic economy hatchback or sedan is genuinely the practical choice — Sri Lanka''s expressways are excellent, but city traffic rewards a smaller footprint. Once hill country or larger groups enter the picture, the added ground clearance of an SUV or the seating capacity of a minivan starts to earn its higher daily rate. Fuel type is worth double-checking too: nearly all rental fleets in Colombo, including YTS''s, run on 95-octane petrol, so factor that into your route planning around fuel stops outside major towns."},{"type":"h2","text":"Do I need an international driving licence to rent a car in Sri Lanka?"},{"type":"p","text":"Yes — but an International Driving Permit on its own is not sufficient. You will also need to convert it into a Sri Lankan Recognition Permit through AA Ceylon, or obtain a Temporary Driving Licence from the Department of Motor Traffic. Since mid-2025, this can be done same-day at a dedicated counter at Colombo''s airport, which has removed the need for most tourists to travel into the city first."},{"type":"h2","text":"Is it safe to self-drive in Sri Lanka as a tourist?"},{"type":"ul","items":["Road conditions vary widely: expressways are modern and well-signed, but rural and hill-country roads can be narrower with less consistent lane markings.","Traffic moves on the left, which suits drivers from left-hand-traffic countries and takes most others roughly a day to adjust to.","Give yourself a low-key first drive — many self-drive travellers do a short local trip before attempting a long highway or mountain route, and it is a reasonable way to build confidence with the car and the road rules."]},{"type":"h2","text":"Key takeaways & next steps"},{"type":"p","text":"Self-drive car rental in Sri Lanka is straightforward once your permit paperwork is sorted and you have matched the vehicle to your actual route rather than just your group size. Get your Recognition Permit or Temporary Driving Licence arranged before pickup, choose an automatic economy car for city and coastal driving (or step up to an SUV or minivan for hill country and larger groups), and confirm the fuel and deposit terms in writing before you sign."},{"type":"quote","text":"Ready to book? Browse YTS Enterprises'' self-drive fleet or message us on WhatsApp for a same-day quote and availability check."},{"type":"p","text":"This article reflects driving-permit requirements as understood at the time of publication (2026). Rules can change — always confirm current requirements directly with the Department of Motor Traffic (dmt.gov.lk) or the Automobile Association of Ceylon before you travel."}]',
  1,
  1,
  1,
  1,
  NOW()
);

INSERT IGNORE INTO `blog` (
  `slug`, `title`, `excerpt`, `metaTitle`, `metaDescription`,
  `category`, `author`, `publishedAt`, `readingMinutes`,
  `coverImage`, `coverAlt`, `tags`, `body`,
  `isFeatured`, `isPublished`, `isActive`,
  `createdBy`, `createdDate`
) VALUES (
  'holiday-homes-galle-sri-lanka',
  'Holiday Homes in Galle, Sri Lanka: How to Book the Right Family Getaway (2026 Guide)',
  'A holiday home near Galle gives you a private, self-contained base — usually a bungalow or villa with multiple bedrooms — for a weekend or week with family or friends, instead of splitting a group across hotel rooms.',
  'Holiday Homes in Galle Sri Lanka (2026 Guide)',
  'Planning a getaway near Galle? Compare holiday home types, group sizes and locations, then book Newlands Bungalow with YTS Enterprises.',
  'Holiday stays',
  'YTS Team',
  '2026-09-06',
  7,
  'https://ytsenterprise.com/images/holiday-home1.png',
  'Colonial-style holiday bungalow veranda near Galle, Sri Lanka, with garden seating suited to family gatherings.',
  '["Galle","holiday home","Newlands","family getaway","Baddegama"]',
  '[{"type":"p","text":"A holiday home near Galle gives you a private, self-contained base — usually a bungalow or villa with multiple bedrooms and shared living space — for a weekend or week with family or friends, instead of splitting a group across separate hotel rooms."},{"type":"h2","text":"Key takeaways"},{"type":"ul","items":["Bungalow-style holiday homes suit multi-generational groups best, since they offer shared common areas plus private rooms — Newlands Bungalow in Baddegama, for example, sleeps groups across five bedrooms with parking for up to ten vehicles.","Galle is roughly 1.5–2 hours from Colombo via the Southern Expressway, making it a realistic weekend option rather than a full-day commitment.","Book directly with the property owner or operator where possible — it typically means clearer answers about what is included (catering, staff, linens) and no third-party platform fees layered on top."]},{"type":"h2","text":"What is a holiday home & how booking works"},{"type":"p","text":"A holiday home is a privately owned property — often a bungalow or villa — rented out for short stays, giving a group exclusive use of bedrooms, bathrooms, and shared living space, rather than individual hotel rooms. Bookings are typically arranged directly with the owner or a local operator, with rates covering the whole property rather than a per-person rate."},{"type":"p","text":"Near Galle, this usually means a colonial-era or colonial-style bungalow set back from the main coast road, with private parking, a garden or grounds, and a layout built around communal living — verandas, shared dining areas, and multiple bedrooms branching off a central space. That structure is what makes holiday homes work so well for reunions, milestone birthdays, and multi-generational trips where a single hotel room per couple does not fit how the group actually wants to spend time together."},{"type":"h2","text":"Step-by-step framework for booking near Galle"},{"type":"ul","items":["Work out your group size and how many bedrooms you actually need — holiday homes are priced per property, so a larger group sharing one booking is usually more cost-effective than splitting across hotel rooms.","Decide how far from Galle Fort you want to be. Properties directly in town put you close to shops and restaurants; properties further out (like Baddegama) trade a short drive for more space, privacy, and often a lower rate.","Ask what is included before you book — catering, housekeeping staff, and linens vary property to property and materially affect the value of the quoted rate.","Check parking and accessibility if you are driving down as a group, especially with multiple vehicles or a self-drive rental.","Confirm the booking directly with the owner or operator, get your dates in writing, and clarify the cancellation or rescheduling policy before paying a deposit.","Plan your route. The Southern Expressway makes Galle a comfortable 1.5–2 hour drive from Colombo — pair the trip with a self-drive rental if you want flexibility to explore Unawatuna, Mirissa, or Koggala while you are down south."]},{"type":"h2","text":"Matching the property to your trip"},{"type":"ul","items":["Colonial-style bungalow (e.g. Newlands Bungalow, Baddegama): best for multi-generational family groups and reunions — shared common space plus private rooms for every age group.","In-town Galle villa: best for groups wanting walkable access to Galle Fort — less driving once you arrive, closer to restaurants and shopping.","Beachfront property: best for couples or small groups prioritising the shoreline — direct beach access, generally at a premium rate."]},{"type":"h2","text":"What to look for in a family-friendly holiday home"},{"type":"p","text":"The details that matter most for a group trip rarely show up in a quick photo scroll: how many bathrooms relative to bedrooms, whether the kitchen and dining space can actually seat everyone at once, and whether the grounds are safe for young children or elderly relatives to move around independently. Past guests at properties like Newlands Bungalow have specifically called out food quality and hospitality as standout factors — worth asking upfront whether meals are arranged on-site or whether you will need to bring in catering separately, since that changes both the cost and the experience considerably."},{"type":"h2","text":"How far is Galle from Colombo for a holiday home trip?"},{"type":"p","text":"Galle is roughly 1.5 to 2 hours from Colombo via the Southern Expressway, depending on traffic and your exact destination. That makes it realistic as a weekend trip rather than something that eats an entire travel day, which is part of why it is one of Sri Lanka''s most-booked short-getaway regions."},{"type":"h2","text":"What should I check before booking a holiday home for a large group?"},{"type":"ul","items":["Bedroom and bathroom count relative to group size — not just total sleeping capacity, since bathroom queues can make or break a group weekend.","Whether meals, staff, or catering are included in the quoted rate, or arranged separately at extra cost.","Parking capacity, especially if part of your group is arriving by self-drive rental car or in multiple vehicles."]},{"type":"h2","text":"Key takeaways & next steps"},{"type":"p","text":"A good holiday home near Galle comes down to matching the property''s layout — bedrooms, shared space, and grounds — to how your specific group actually wants to spend the weekend, then confirming what is included before you pay a deposit. Properties like Newlands Bungalow work well precisely because they are built for groups rather than couples, with room to spread out across five bedrooms and parking for up to ten cars."},{"type":"quote","text":"Ready to book your getaway? Check availability for Newlands Bungalow or message YTS Enterprises on WhatsApp to lock in your dates."}]',
  1,
  1,
  1,
  1,
  NOW()
);

INSERT IGNORE INTO `blog` (
  `slug`, `title`, `excerpt`, `metaTitle`, `metaDescription`,
  `category`, `author`, `publishedAt`, `readingMinutes`,
  `coverImage`, `coverAlt`, `tags`, `body`,
  `isFeatured`, `isPublished`, `isActive`,
  `createdBy`, `createdDate`
) VALUES (
  'apartment-rental-guide-colombo',
  'Renting an Apartment in Colombo: Complete Guide for Tenants (2026)',
  'Renting an apartment in Colombo works like most major cities — you view, negotiate, sign a lease, and pay a deposit — but deposit and advance-rent norms vary far more by landlord than tenants usually expect.',
  'Renting an Apartment in Colombo: Tenant Guide',
  'Renting an apartment in Colombo? Learn what deposits, lease terms and viewings actually look like, then browse verified listings with YTS Enterprises.',
  'Properties',
  'YTS Team',
  '2026-09-06',
  7,
  'https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=1600&q=80',
  'Modern apartment building in Colombo 3, Sri Lanka, illustrating typical rental units available to tenants.',
  '["Colombo apartments","tenant guide","lease","deposit","rental"]',
  '[{"type":"p","text":"Renting an apartment in Colombo works similarly to most major cities — you view, negotiate terms, sign a lease, and pay a deposit — but the deposit and advance-rent norms vary far more by landlord than tenants usually expect, so it pays to confirm terms in writing before you commit."},{"type":"h2","text":"Key takeaways"},{"type":"ul","items":["Deposits typically range from 1 to 6 months'' rent depending on the landlord and whether an agent is involved — there is no single fixed standard across Colombo, so always get the figure confirmed before you view.","Leases longer than 12 months are often registered with local authorities, which gives both tenant and landlord clearer legal footing than an informal agreement.","A written lease should always specify deposit refund terms, maintenance responsibilities, and what happens if either party wants to end the agreement early."]},{"type":"h2","text":"What renting an apartment involves in Colombo"},{"type":"p","text":"Renting an apartment in Colombo means signing a tenancy or lease agreement with a landlord (directly or through an agent), paying an upfront deposit plus monthly or advance rent, and receiving a unit for an agreed period — typically furnished or unfurnished, with parking and amenities varying by building."},{"type":"p","text":"Most rentals in Colombo''s popular districts — Colombo 3, Colombo 5, Colombo 6, and nearby Dehiwala — are arranged either directly with the property owner or through a local real estate agent who manages viewings and paperwork. Unlike a hotel or short-term stay, a lease locks in your rate and terms for the agreed period, which is why reading the fine print on deposit refunds and maintenance responsibility matters more here than almost anywhere else in the process."},{"type":"h2","text":"Step-by-step framework for renting in Colombo"},{"type":"ul","items":["Set your budget and must-haves — furnished vs. unfurnished, number of bedrooms, proximity to work or school, and whether dedicated parking matters to you.","Search listings or work with an agent covering the areas you are considering; comparing a handful of units in the same district gives you a realistic sense of going rates.","Schedule viewings and take note of building condition, water pressure, backup power, and noise — details that rarely come through clearly in photos.","Negotiate rent, deposit, and any service or agent fees directly, since these figures are rarely fixed and do vary between landlords.","Have the lease reviewed before signing — either by a lawyer or a trusted local contact — checking specifically for deposit refund conditions and maintenance responsibilities.","Register leases longer than 12 months where applicable, which gives you stronger legal standing if a dispute arises later.","Set up utilities in your name if they are not already included, and confirm exactly what the monthly rent does and does not cover."]},{"type":"h2","text":"What deposit and lease terms typically look like"},{"type":"ul","items":["Security deposit: typically 1–6 months'' rent (varies widely by landlord/agent) — confirm refund timeline and any deduction conditions in writing.","Advance rent: often 1–6 months paid upfront — confirm whether this is separate from or part of the deposit.","Minimum lease term: commonly 12 months — confirm early termination notice period and any penalty.","Registration: recommended for leases over 12 months — confirm whether the landlord or tenant handles registration."]},{"type":"h2","text":"What to check before you sign"},{"type":"p","text":"The single biggest source of disputes in Colombo apartment rentals is not the rent amount — it is ambiguity around the deposit refund. A lease that clearly states the deposit is fully refundable minus documented damages, with a defined timeline for return, protects both sides far better than a verbal understanding. It is also worth confirming upfront whether the quoted rent includes service charges (common in apartment complexes with shared facilities like generators, security, or a gym), since these can meaningfully change your real monthly cost."},{"type":"h2","text":"How much deposit do I need to rent an apartment in Colombo?"},{"type":"p","text":"It depends on the landlord — deposits commonly range from one month''s rent up to six months'', and some landlords also ask for several months of rent paid in advance on top of that. There is no single citywide standard, so always get the exact figure and refund terms confirmed in writing before you commit to a viewing or a booking fee."},{"type":"h2","text":"Can foreigners rent an apartment in Colombo?"},{"type":"ul","items":["Yes, foreigners are permitted to rent residential property in Sri Lanka under standard tenancy arrangements.","Long-term leases (over 12 months) are often registered with local authorities, which is worth doing for the added legal protection.","Having a lawyer or trusted local agent review the lease before signing is strongly advisable, particularly around deposit and termination clauses."]},{"type":"h2","text":"Key takeaways & next steps"},{"type":"p","text":"Renting an apartment in Colombo is a straightforward process once you know that deposit and advance-rent terms genuinely vary by landlord — the key is getting everything confirmed in writing before you commit, rather than assuming a \\"standard\\" rate that does not really exist across the city. Compare a few listings in your target district, review the lease carefully, and register longer-term agreements for added protection."},{"type":"quote","text":"Ready to start looking? Browse current apartment listings in Colombo — including units in Colombo 3, Colombo 6, and Dehiwala — or message YTS Enterprises on WhatsApp to arrange a viewing."},{"type":"p","text":"This article provides general guidance based on common rental practice in Colombo; specific deposit and lease terms are set by individual landlords and should always be confirmed directly before signing."}]',
  0,
  1,
  1,
  1,
  NOW()
);
